INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('canActOnWaybillStage', 'Can act on waybill stage', '{"rules": [{"allow": "stage:submission:act::allow"}]}', 'Submission stage permission', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('hr.leave.approve', 'HR leave approval', '{"rules": [{"when": "actor.id == resource.submitterId", "allow": "hr:leave:decide_self::allow"}, {"when": "actor.dept_id == resource.submitterDeptId", "allow": "hr:leave:approve::allow"}, {"allow": "hr:leave:approve::allow"}]}', 'Self approve own OR dept manager approves OR HR', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('hr.leave.request', 'HR leave request', '{"rules": [{"allow": "hr:leave:submit::allow"}]}', 'Submit own leave request', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('recallWaybill', 'Recall a waybill', '{"rules": [{"when": "actor.id == resource.submitterId && resource.currentStage != ''disbursed''", "allow": "finance:waybill:recall::allow"}, {"when": "actor.level <= 2", "allow": "admin:system:bypass::allow"}]}', 'Recall a waybill: submitter (not yet disbursed) or CEO/admin', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('sales.draft.discard', 'Sales draft discard', '{"rules": [{"when": "actor.id == resource.submitterId", "allow": "sales:draft:discard::allow"}, {"allow": "sales:draft:discard::allow"}]}', 'Submitter can discard their own draft; supervisor can discard any', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.accounting_authorization', 'Waybill accounting authorization', '{"rules": [{"allow": "stage:accounting_authorization:act::allow"}]}', 'Accounting manager authorization', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.accounting_supervision', 'Waybill accounting supervision', '{"rules": [{"allow": "stage:accounting_supervision:act::allow"}]}', 'Accounting supervisor review', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.accounting_verification', 'Waybill accounting verification', '{"rules": [{"allow": "stage:accounting_verification:act::allow"}]}', 'Accounting officer verification', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.ceo_authorization', 'Waybill CEO authorization', '{"rules": [{"deny": "stage:ceo_authorization:act::allow", "when": "(total_amount_thb == null || total_amount_thb < 200000)", "reason": "CEO authorization not required: amount under 200k THB"}, {"allow": "stage:ceo_authorization:act::allow"}]}', 'CEO authorization only required when total >= 200,000 THB', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.cfo_authorization', 'Waybill CFO authorization', '{"rules": [{"deny": "stage:cfo_authorization:act::allow", "when": "(total_amount_thb == null || total_amount_thb < 200000)", "reason": "CFO authorization skipped: amount under 200k THB"}, {"allow": "stage:cfo_authorization:act::allow"}]}', 'CFO authorization required when total >= 200,000 THB', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.dept_authorization', 'Waybill dept authorization', '{"rules": [{"when": "actor.dept_id == resource.submitterDeptId", "allow": "stage:dept_authorization:act::allow"}]}', 'Manager authorization requires same dept as submitter', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.dept_verification', 'Waybill dept verification', '{"rules": [{"when": "actor.dept_id == resource.submitterDeptId", "allow": "stage:dept_verification:act::allow"}]}', 'Actor can act on dept_verification only when in submitter dept', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.disbursement_authorization', 'Waybill disbursement authorization', '{"rules": [{"allow": "stage:disbursement_authorization:act::allow"}]}', 'Finance disbursement lead', 't', '1');
INSERT INTO perm.policies (id, name, ast, description, enabled, version) VALUES ('waybill.po_cfo', 'PO CFO authorization', '{"rules": [{"allow": "stage:po_cfo:act::allow"}]}', 'CFO sign-off on PO', 't', '1');
