\set ON_ERROR_STOP on

BEGIN;


SELECT setval(pg_get_serial_sequence('folio.ai_providers', 'id'), max(id), true) FROM folio.ai_providers;
SELECT setval(pg_get_serial_sequence('folio.ai_models', 'id'), max(id), true) FROM folio.ai_models;
SELECT setval(pg_get_serial_sequence('folio.ai_staff', 'id'), max(id), true) FROM folio.ai_staff;
SELECT setval(pg_get_serial_sequence('folio.ai_assignments', 'id'), max(id), true) FROM folio.ai_assignments;

DO $do$
BEGIN
  IF (SELECT count(*) FROM folio.chart_of_accounts) <> 32 THEN
    RAISE EXCEPTION 'Expected 32 chart-of-account rows';
  END IF;
  IF (SELECT count(*) FROM perm.departments) <> 5 THEN
    RAISE EXCEPTION 'Expected 5 departments';
  END IF;
  IF (SELECT count(*) FROM perm.roles) <> 14 THEN
    RAISE EXCEPTION 'Expected 14 roles';
  END IF;
  IF (SELECT count(*) FROM perm.permissions) <> 199 THEN
    RAISE EXCEPTION 'Expected 199 permissions';
  END IF;
  IF (SELECT count(*) FROM perm.role_permissions) <> 606 THEN
    RAISE EXCEPTION 'Expected 606 role grants';
  END IF;
  IF (SELECT count(*) FROM perm.department_permissions) <> 84 THEN
    RAISE EXCEPTION 'Expected 84 department grants';
  END IF;
  IF (SELECT count(*) FROM perm.tiles) <> 31 THEN
    RAISE EXCEPTION 'Expected 31 tiles';
  END IF;
  IF EXISTS (SELECT 1 FROM folio.users) THEN
    RAISE EXCEPTION 'The baseline seed must not create user identities';
  END IF;
  IF EXISTS (SELECT 1 FROM perm.audit) THEN
    RAISE EXCEPTION 'The baseline seed must not create audit history';
  END IF;
END
$do$;

COMMIT;
